import assert from 'node:assert/strict';
import { test } from 'vitest';
import { LinkVerifier } from '@/index';
import { LinkFixture } from '@/testing/index';

test('accepts a Link token and rejects a forged token without WBA', async () => {
  const link = await LinkFixture.create();
  const verifier = new LinkVerifier({
    origin: 'shop.example',
    fetchImpl: link.fetchImpl(),
  });

  const token = await link.mint();
  assert.equal(
    (await verifier.verifyAttestation(token.authorization)).valid,
    true,
  );

  const forged = await link.mint({ corruptAuthenticator: true });
  const result = await verifier.verifyAttestation(forged.authorization);
  assert.equal(result.valid, false);
  if (!result.valid)
    assert.equal(result.failures[0]?.code, 'invalid_private_token');
});

import assert from 'node:assert/strict';
import { beforeAll, describe, it, vi } from 'vitest';
import { assertFailed } from '@/__tests__/helpers';
import { clearJwksCache } from '@/claims';
import { LinkVerifier, VerificationError } from '@/index';
import { fromBase64, toBase64Std, toBase64url } from '@/internal/bytes';
import { trimTrailingSlashes } from '@/internal/strings';
import { LinkIssuer } from '@/issuer';
import { CredentialFixture, combineFetch, LinkFixture } from '@/testing/index';

const AUD = 'https://events.example';
const OPTIONS = { nonce: 'registration-nonce', requiredClaims: ['email'] };
const segment = (value: unknown) =>
  Buffer.from(JSON.stringify(value)).toString('base64url');

function replaceSegment(
  presentation: string,
  jwt: 'issuer' | 'holder',
  part: 0 | 1,
  value: unknown,
): string {
  const pieces = presentation.split('~');
  const index = jwt === 'issuer' ? 0 : pieces.length - 1;
  const segments = pieces[index]!.split('.');
  segments[part] = segment(value);
  pieces[index] = segments.join('.');
  return pieces.join('~');
}

function offlineVerifier() {
  const fetchImpl = vi.fn(async () => {
    throw new Error('unexpected issuer request');
  });
  return { verifier: new LinkVerifier({ origin: AUD, fetchImpl }), fetchImpl };
}

describe('bounded credential parsing', () => {
  it('rejects oversized fields before parsing or fetching', async () => {
    const { verifier, fetchImpl } = offlineVerifier();
    assert.match(
      assertFailed(
        await verifier.verifyAttestation(`PrivateToken ${' '.repeat(8192)}`),
        'malformed_protocol_input',
      ).message,
      /8192-character limit/,
    );
    assert.match(
      assertFailed(
        await verifier.verifyClaims('~'.repeat(65537), OPTIONS),
        'invalid_claims_presentation',
      ).message,
      /65536-character limit/,
    );
    assert.equal(fetchImpl.mock.calls.length, 0);
  });

  it('rejects padding runs and embedded newlines without an issuer request', async () => {
    const { verifier, fetchImpl } = offlineVerifier();
    for (const input of [
      `PrivateToken token="${'='.repeat(4000)}A"`,
      `PrivateToken token="${'='.repeat(400)}A"`,
      `PrivateToken ${' '.repeat(4000)}x\nx`,
      `PrivateToken token=${' '.repeat(4000)}x\rx`,
    ]) {
      assertFailed(
        await verifier.verifyAttestation(input),
        'malformed_protocol_input',
      );
    }
    assert.equal(fetchImpl.mock.calls.length, 0);
  });

  it('compares slash-heavy unsigned issuers without fetching', async () => {
    const { verifier, fetchImpl } = offlineVerifier();
    const issuerJwt = [
      segment({ typ: 'dc+sd-jwt', alg: 'EdDSA' }),
      segment({
        iss: `https://api.link.com/${'/'.repeat(32000)}x`,
        vct: 'example',
      }),
      'AA',
    ].join('.');
    assert.match(
      assertFailed(
        await verifier.verifyClaims(`${issuerJwt}~e30.e30.AA`, OPTIONS),
        'invalid_claims_presentation',
      ).message,
      /credential issuer/,
    );
    assert.equal(fetchImpl.mock.calls.length, 0);
  });

  it('preserves issuer slash normalization without removing internal slashes', () => {
    assert.equal(
      trimTrailingSlashes('https://api.link.com///'),
      'https://api.link.com',
    );
    const path = `https://api.link.com/${'/'.repeat(32000)}x`;
    assert.equal(trimTrailingSlashes(path), path);
    assert.equal(
      new LinkIssuer({ issuer: 'https://api.link.com///' }).issuer,
      'https://api.link.com',
    );
    assert.equal(trimTrailingSlashes(''), '');
  });

  it('accepts standard and URL-safe base64 with valid optional padding', () => {
    for (let size = 0; size < 40; size++) {
      const bytes = new Uint8Array(size).fill(255);
      assert.deepEqual(fromBase64(toBase64Std(bytes)), bytes);
      assert.deepEqual(fromBase64(toBase64url(bytes)), bytes);
      assert.deepEqual(
        fromBase64(
          toBase64Std(bytes).replaceAll('+', '-').replaceAll('/', '_'),
        ),
        bytes,
      );
    }
  });

  it('rejects misplaced or excess base64 padding and impossible lengths', () => {
    for (const input of [
      'A',
      'AA=',
      'A===',
      'AAAA=',
      '=AAA',
      'AA=A',
      `${'='.repeat(32000)}A`,
    ]) {
      assert.throws(() => fromBase64(input), /invalid base64/);
    }
  });
});

describe('JWT object shapes', () => {
  let verifier: LinkVerifier;
  let presentation: string;
  let authorization: string;

  beforeAll(async () => {
    clearJwksCache();
    const link = await LinkFixture.create();
    const credential = await CredentialFixture.create({
      issuerUrl: link.issuer,
      claims: { email: 'guest@example.com' },
    });
    verifier = new LinkVerifier({
      origin: AUD,
      fetchImpl: combineFetch(link.fetchImpl(), credential.fetchImpl()),
    });
    presentation = await credential.present({
      aud: AUD,
      nonce: OPTIONS.nonce,
      disclose: ['email'],
    });
    authorization = (await link.mint()).authorization;
    assert.equal(
      (await verifier.verifyClaims(presentation, OPTIONS)).valid,
      true,
    );
  });

  for (const jwt of ['issuer', 'holder'] as const) {
    for (const part of [0, 1] as const) {
      for (const value of [null, [], 'text', 42, true]) {
        it(`rejects ${jwt} ${part === 0 ? 'header' : 'payload'} containing ${JSON.stringify(value)}`, async () => {
          assert.match(
            assertFailed(
              await verifier.verifyClaims(
                replaceSegment(presentation, jwt, part, value),
                OPTIONS,
              ),
              'invalid_claims_presentation',
            ).message,
            /JSON objects/,
          );
        });
      }
    }
    for (const field of ['typ', 'alg']) {
      it(`rejects an object-valued ${jwt} ${field} without invoking its toString`, async () => {
        const header = {
          typ: jwt === 'issuer' ? 'dc+sd-jwt' : 'kb+jwt',
          alg: 'EdDSA',
          [field]: { toString: null },
        };
        assertFailed(
          await verifier.verifyClaims(
            replaceSegment(presentation, jwt, 0, header),
            OPTIONS,
          ),
          'invalid_claims_presentation',
        );
      });
    }
  }

  it('only the OrThrow API throws, with a VerificationError', async () => {
    await assert.rejects(
      verifier.verifyClaimsOrThrow(
        replaceSegment(presentation, 'issuer', 0, null),
        OPTIONS,
      ),
      (error: unknown) =>
        error instanceof VerificationError &&
        error.code === 'invalid_claims_presentation',
    );
  });

  it('still verifies valid credentials after malformed input and at the header size limit', async () => {
    const padded = `${authorization}, extra="${'x'.repeat(8192 - authorization.length - 10)}"`;
    assert.equal(padded.length, 8192);
    assert.equal((await verifier.verifyAttestation(padded)).valid, true);
    assertFailed(
      await verifier.verifyAttestation(`${padded} `),
      'malformed_protocol_input',
    );
    assert.equal(
      (await verifier.verifyClaims(presentation, OPTIONS)).valid,
      true,
    );
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { TransactionsResource } from '@/resources/transactions';

const mockFetch = vi.fn();
const getAccessToken = vi.fn();

function mockFetchResponse(status: number, body: Record<string, unknown>) {
  mockFetch.mockResolvedValue({
    status,
    statusText: '',
    headers: new Headers(),
    text: async () => JSON.stringify(body),
  });
}

describe('TransactionsResource', () => {
  let repo: TransactionsResource;

  beforeEach(() => {
    vi.stubGlobal('fetch', mockFetch);
    vi.clearAllMocks();
    vi.stubEnv('LINK_API_BASE_URL', undefined);
    getAccessToken.mockResolvedValue('test_token');
    repo = new TransactionsResource({ getAccessToken });
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    vi.unstubAllEnvs();
  });

  it('GETs the Link API transactions endpoint with bearer auth', async () => {
    mockFetchResponse(200, {
      data: [
        {
          id: 'lbctxn_123',
          source_id: null,
          amount: -979,
          currency: 'usd',
          created_date: '2026-06-08',
          description: 'Chase',
          origin: 'external_connection',
          category: 'credit_card_payment',
          status: 'succeeded',
        },
      ],
      has_more: true,
    });

    const result = await repo.list();

    expect(mockFetch).toHaveBeenCalledOnce();
    const [url, opts] = mockFetch.mock.calls[0]!;
    expect(url).toBe('https://api.link.com/transactions');
    expect(opts.method).toBe('GET');
    expect(opts.headers.Authorization).toBe('Bearer test_token');

    expect(result).toEqual({
      data: [
        {
          id: 'lbctxn_123',
          source_id: null,
          amount: -979,
          currency: 'usd',
          created_date: '2026-06-08',
          description: 'Chase',
          origin: 'external_connection',
          category: 'credit_card_payment',
          status: 'succeeded',
        },
      ],
      has_more: true,
    });
  });

  it('encodes optional list params in the query string', async () => {
    mockFetchResponse(200, { data: [] });

    await repo.list({
      limit: 50,
      starting_after: 'cursor_a',
      ending_before: 'cursor_b',
      start_date: '2026-06-08',
      end_date: '2026-06-09',
      category: 'shopping',
      origin: 'link',
      sources: ['csmrpd_a', 'csmrpd_b'],
    });

    const url = new URL(mockFetch.mock.calls[0]![0]);
    expect(url.searchParams.get('limit')).toBe('50');
    expect(url.searchParams.get('starting_after')).toBe('cursor_a');
    expect(url.searchParams.get('ending_before')).toBe('cursor_b');
    expect(url.searchParams.get('date_start')).toBe('2026-06-08');
    expect(url.searchParams.get('date_end')).toBe('2026-06-09');
    expect(url.searchParams.get('category')).toBe('shopping');
    expect(url.searchParams.get('origin')).toBe('link');
    expect(url.searchParams.getAll('sources[]')).toEqual([
      'csmrpd_a',
      'csmrpd_b',
    ]);
    expect(url.searchParams.has('start_date')).toBe(false);
    expect(url.searchParams.has('end_date')).toBe(false);
    expect(url.searchParams.has('transaction_category')).toBe(false);
  });

  it('uses an explicitly configured base URL', async () => {
    repo = new TransactionsResource({
      getAccessToken,
      apiBaseUrl: 'https://api.qa.link.com',
    });
    mockFetchResponse(200, { data: [] });

    await repo.list();

    expect(mockFetch.mock.calls[0]![0]).toBe(
      'https://api.qa.link.com/transactions',
    );
  });

  it('refreshes the token and retries once on 401', async () => {
    mockFetch
      .mockResolvedValueOnce({
        status: 401,
        statusText: '',
        headers: new Headers(),
        text: async () => JSON.stringify({ error: 'expired_token' }),
      })
      .mockResolvedValueOnce({
        status: 200,
        statusText: '',
        headers: new Headers(),
        text: async () => JSON.stringify({ data: [] }),
      });
    getAccessToken
      .mockResolvedValueOnce('test_token')
      .mockResolvedValueOnce('fresh_token');

    const result = await repo.list();

    expect(result).toEqual({ data: [] });
    expect(getAccessToken).toHaveBeenNthCalledWith(1);
    expect(getAccessToken).toHaveBeenNthCalledWith(2, { forceRefresh: true });
    expect(mockFetch).toHaveBeenCalledTimes(2);
    expect(mockFetch.mock.calls[1]![1].headers.Authorization).toBe(
      'Bearer fresh_token',
    );
  });

  it('throws API errors with the response message', async () => {
    mockFetchResponse(500, { message: 'boom' });

    await expect(repo.list()).rejects.toThrow(
      'Failed to list transactions (500): boom',
    );
  });

  it('throws when no access token is available', async () => {
    getAccessToken.mockRejectedValueOnce(new Error('Missing access token'));

    await expect(repo.list()).rejects.toThrow('Missing access token');
  });

  it('throws when the response shape is invalid', async () => {
    mockFetchResponse(200, { data: [{ id: 'lbctxn_123' }] });

    await expect(repo.list()).rejects.toMatchObject({
      code: 'invalid_response',
      status: 200,
    });
  });
});

/**
 * A stand-in for a Link-issued SD-JWT-VC and a holder presenting it.
 *
 * Real crypto, not a mock: a genuine Ed25519 issuer key signs the credential, a
 * separate holder key signs the KB-JWT, and the digests are computed the way
 * RFC 9901 specifies. That matters because the mistakes worth catching in this
 * lane are all encoding mistakes, and a mock cannot make them.
 *
 * Exported so a verifier integrating this SDK can test its own 401 handling
 * without reimplementing SD-JWT-VC. Everything a presentation needs to be made
 * *wrong* is reachable through `present()`, so negative tests are writable too.
 */
import { asBufferSource, toBase64url, utf8 } from '../internal/bytes.js';
import { type Jwk, jwkThumbprint, sha256 } from '../internal/crypto.js';

const subtle = globalThis.crypto.subtle;

const CREDENTIAL_KID = 'link-cred-1';

export interface PresentOptions {
  /** The verifier this presentation is for. Becomes the KB-JWT `aud`. */
  aud: string;
  /** The nonce from the challenge being answered. */
  nonce: string;
  /** Claim names to disclose. Anything omitted stays hidden. */
  disclose: string[];
  /** Overrides `sd_hash`, to test that the binding is actually checked. */
  sdHashOverride?: string;
  /** Overrides the KB-JWT `typ`, which must be `kb+jwt`. */
  typOverride?: string;
  /** Overrides the KB-JWT `iat`. */
  iat?: number;
}

export interface CredentialFixtureOptions {
  issuerUrl: string;
  claims: Record<string, unknown>;
  /** Omit `exp`, to test that a credential without one is refused. */
  omitExp?: boolean;
  /** Overrides the issuer JWT `typ`, which must be `dc+sd-jwt` or `vc+sd-jwt`. */
  typOverride?: string;
  /** Seconds from now until `exp`. Negative mints an already-expired credential. */
  expiresInSeconds?: number;
  /**
   * Extra top-level members merged into the credential payload.
   *
   * For minting a *validly signed* credential whose structure is wrong, which is
   * the only way to reach the checks that run after signature verification. A
   * hand-assembled unsigned credential cannot test them, because it is rejected
   * earlier and for a different reason.
   */
  extraPayload?: Record<string, unknown>;
  /** Rewrites the computed `_sd` digest list, e.g. to repeat one. */
  rewriteSd?: (digests: string[]) => unknown;
  /**
   * Additional raw disclosure strings, committed to in `_sd` and presented.
   * Each is the base64url of whatever JSON you want, so a reserved claim name or
   * a two-element array-element disclosure is reachable.
   */
  extraDisclosures?: unknown[];
}

export class CredentialFixture {
  readonly issuerJwt: string;
  readonly disclosures: readonly string[];
  readonly holderThumbprint: string;
  readonly issuerJwk: Jwk;

  private readonly claimNames: string[];
  private readonly holderPrivateKey: CryptoKey;
  private readonly issuerUrl: string;
  private readonly alwaysPresent: string[];

  private constructor(init: {
    issuerJwt: string;
    disclosures: string[];
    holderThumbprint: string;
    issuerJwk: Jwk;
    claimNames: string[];
    holderPrivateKey: CryptoKey;
    issuerUrl: string;
    alwaysPresent: string[];
  }) {
    this.issuerJwt = init.issuerJwt;
    this.disclosures = init.disclosures;
    this.holderThumbprint = init.holderThumbprint;
    this.issuerJwk = init.issuerJwk;
    this.claimNames = init.claimNames;
    this.holderPrivateKey = init.holderPrivateKey;
    this.issuerUrl = init.issuerUrl;
    this.alwaysPresent = init.alwaysPresent;
  }

  static async create(
    options: CredentialFixtureOptions,
  ): Promise<CredentialFixture> {
    const issuerPair = (await subtle.generateKey({ name: 'Ed25519' }, true, [
      'sign',
      'verify',
    ])) as CryptoKeyPair;
    const issuerJwk = await exportPublicJwk(issuerPair.publicKey);
    issuerJwk.kid = CREDENTIAL_KID;

    const holderPair = (await subtle.generateKey({ name: 'Ed25519' }, true, [
      'sign',
      'verify',
    ])) as CryptoKeyPair;
    const holderJwk = await exportPublicJwk(holderPair.publicKey);

    // One disclosure per claim: [salt, name, value], per RFC 9901 section 4.2.
    const disclosures: string[] = [];
    const sd: string[] = [];
    const claimNames = Object.keys(options.claims);
    for (const name of claimNames) {
      const salt = toBase64url(
        globalThis.crypto.getRandomValues(new Uint8Array(16)),
      );
      const disclosure = segment([salt, name, options.claims[name]]);
      disclosures.push(disclosure);
      // The digest is over the base64url *string*, not the decoded bytes.
      sd.push(toBase64url(await sha256(utf8(disclosure))));
    }

    // Raw extras, committed to and always presented. These exist so a structurally
    // invalid disclosure can be carried by an otherwise valid, correctly signed
    // credential.
    const alwaysPresent: string[] = [];
    for (const raw of options.extraDisclosures ?? []) {
      const disclosure = segment(raw);
      alwaysPresent.push(disclosure);
      sd.push(toBase64url(await sha256(utf8(disclosure))));
    }

    const header = segment({
      alg: 'EdDSA',
      typ: options.typOverride ?? 'dc+sd-jwt',
      kid: CREDENTIAL_KID,
    });
    const now = Math.floor(Date.now() / 1000);
    const payload = segment({
      iss: options.issuerUrl,
      vct: `${options.issuerUrl}/identity/credentials/v1`,
      ...(options.omitExp === true
        ? {}
        : { exp: now + (options.expiresInSeconds ?? 86400) }),
      cnf: { jwk: holderJwk },
      _sd: options.rewriteSd !== undefined ? options.rewriteSd(sd) : sd,
      _sd_alg: 'sha-256',
      ...(options.extraPayload ?? {}),
    });
    const issuerSig = new Uint8Array(
      await subtle.sign(
        { name: 'Ed25519' },
        issuerPair.privateKey,
        asBufferSource(utf8(`${header}.${payload}`)),
      ),
    );

    return new CredentialFixture({
      issuerJwt: `${header}.${payload}.${toBase64url(issuerSig)}`,
      disclosures,
      holderThumbprint: await jwkThumbprint(holderJwk),
      issuerJwk,
      claimNames,
      holderPrivateKey: holderPair.privateKey,
      issuerUrl: options.issuerUrl,
      alwaysPresent,
    });
  }

  /** Builds a holder presentation disclosing the named claims. */
  async present(options: PresentOptions): Promise<string> {
    const kept: string[] = [];
    for (let i = 0; i < this.disclosures.length; i++) {
      const name = this.claimNames[i];
      const disclosure = this.disclosures[i];
      if (
        name !== undefined &&
        disclosure !== undefined &&
        options.disclose.includes(name)
      ) {
        kept.push(disclosure);
      }
    }
    // The trailing tilde is part of what `sd_hash` covers.
    const sdPart = `${[this.issuerJwt, ...kept, ...this.alwaysPresent].join('~')}~`;
    const kbHeader = segment({
      typ: options.typOverride ?? 'kb+jwt',
      alg: 'EdDSA',
    });
    const kbPayload = segment({
      aud: options.aud,
      nonce: options.nonce,
      iat: options.iat ?? Math.floor(Date.now() / 1000),
      sd_hash:
        options.sdHashOverride ?? toBase64url(await sha256(utf8(sdPart))),
    });
    const kbSig = new Uint8Array(
      await subtle.sign(
        { name: 'Ed25519' },
        this.holderPrivateKey,
        asBufferSource(utf8(`${kbHeader}.${kbPayload}`)),
      ),
    );
    return `${sdPart}${kbHeader}.${kbPayload}.${toBase64url(kbSig)}`;
  }

  /** Serves this credential issuer's JWKS at the well-known location. */
  fetchImpl(): typeof fetch {
    const jwksUrl = `${this.issuerUrl}/.well-known/aap-issuer/jwks.json`;
    const jwk = this.issuerJwk;
    return (async (input: RequestInfo | URL) => {
      if (input.toString() === jwksUrl) {
        return new Response(JSON.stringify({ keys: [jwk] }), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }
      return new Response('not found', { status: 404 });
    }) as typeof fetch;
  }
}

async function exportPublicJwk(key: CryptoKey): Promise<Jwk> {
  const jwk = (await subtle.exportKey('jwk', key)) as Jwk & {
    key_ops?: unknown;
    ext?: unknown;
  };
  // WebCrypto adds these on export; they are not part of a published JWK and
  // some runtimes refuse to import a key that carries them.
  delete jwk.key_ops;
  delete jwk.ext;
  return jwk;
}

function segment(value: unknown): string {
  return toBase64url(utf8(JSON.stringify(value)));
}

import { describe, expect, it, vi } from 'vitest';
import { LinkResponseError } from '@/errors';
import { IdentityCredentialsResource } from '@/resources/identity-credentials';

function jsonResponse(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

const PUBLIC_JWK = {
  kty: 'OKP' as const,
  crv: 'Ed25519' as const,
  x: 'public-key',
};

describe('IdentityCredentialsResource', () => {
  it('issues through the discovered credential endpoint', async () => {
    const fetchMock = vi.fn(
      async (input: RequestInfo | URL, init?: RequestInit) => {
        const url = String(input);
        if (url === 'https://api.link.com/.well-known/aap-issuer') {
          expect(init).toMatchObject({
            method: 'GET',
            redirect: 'manual',
          });
          return jsonResponse({
            issuer: 'https://api.link.com',
            credential_endpoint: 'https://api.link.com/identity/credentials',
          });
        }
        expect(url).toBe('https://api.link.com/identity/credentials');
        expect(init?.redirect).toBe('manual');
        expect(init?.headers).toMatchObject({
          Authorization: 'Bearer access-token',
        });
        expect(JSON.parse(String(init?.body))).toEqual({
          cnf: { jwk: PUBLIC_JWK },
        });
        return jsonResponse({
          credential: 'issuer-jwt~',
          issuer: 'https://api.link.com',
          expires_at: '2026-08-25T00:00:00Z',
        });
      },
    );
    const resource = new IdentityCredentialsResource({
      apiBaseUrl: 'https://attacker.example',
      accessToken: 'access-token',
      fetch: fetchMock,
    });

    await expect(
      resource.issue({ cnf: { jwk: PUBLIC_JWK } }),
    ).resolves.toMatchObject({
      credential: 'issuer-jwt~',
      issuer: 'https://api.link.com',
    });
    expect(fetchMock).toHaveBeenCalledTimes(2);
  });

  it('rejects metadata for a different issuer before authentication', async () => {
    const getAccessToken = vi.fn(async () => 'secret');
    const fetchMock = vi.fn(
      async (_input: RequestInfo | URL, _init?: RequestInit) =>
        jsonResponse({
          issuer: 'https://attacker.example',
          credential_endpoint: 'https://api.link.com/identity/credentials',
        }),
    );
    const resource = new IdentityCredentialsResource({
      getAccessToken,
      fetch: fetchMock,
    });

    await expect(
      resource.issue({ cnf: { jwk: PUBLIC_JWK } }),
    ).rejects.toBeInstanceOf(LinkResponseError);
    expect(fetchMock).toHaveBeenCalledTimes(1);
    expect(getAccessToken).not.toHaveBeenCalled();
  });

  it('rejects an off-origin credential endpoint before authentication', async () => {
    const getAccessToken = vi.fn(async () => 'secret');
    const fetchMock = vi.fn(
      async (_input: RequestInfo | URL, _init?: RequestInit) =>
        jsonResponse({
          issuer: 'https://api.link.com',
          credential_endpoint: 'https://attacker.example/credential',
        }),
    );
    const resource = new IdentityCredentialsResource({
      getAccessToken,
      fetch: fetchMock,
    });

    await expect(resource.issue({ cnf: { jwk: PUBLIC_JWK } })).rejects.toThrow(
      'credential_endpoint must be an HTTPS URL',
    );
    expect(fetchMock).toHaveBeenCalledTimes(1);
    expect(getAccessToken).not.toHaveBeenCalled();
  });

  it('refuses issuer metadata redirects', async () => {
    const fetchMock = vi.fn(
      async (_input: RequestInfo | URL, _init?: RequestInit) =>
        new Response('', {
          status: 302,
          headers: { Location: 'https://attacker.example/metadata' },
        }),
    );
    const resource = new IdentityCredentialsResource({
      accessToken: 'access-token',
      fetch: fetchMock,
    });

    await expect(resource.issue({ cnf: { jwk: PUBLIC_JWK } })).rejects.toThrow(
      'Refused redirect',
    );
    expect(fetchMock).toHaveBeenCalledTimes(1);
  });

  it('wraps malformed credential responses in LinkResponseError', async () => {
    const fetchMock = vi.fn(
      async (input: RequestInfo | URL, _init?: RequestInit) =>
        String(input).endsWith('/.well-known/aap-issuer')
          ? jsonResponse({
              issuer: 'https://api.link.com',
              credential_endpoint: 'https://api.link.com/identity/credentials',
            })
          : jsonResponse({ credential: 42 }),
    );
    const resource = new IdentityCredentialsResource({
      accessToken: 'access-token',
      fetch: fetchMock,
    });

    await expect(
      resource.issue({ cnf: { jwk: PUBLIC_JWK } }),
    ).rejects.toBeInstanceOf(LinkResponseError);
  });

  it('rejects a credential response from a different issuer', async () => {
    const fetchMock = vi.fn(
      async (input: RequestInfo | URL, _init?: RequestInit) =>
        String(input).endsWith('/.well-known/aap-issuer')
          ? jsonResponse({
              issuer: 'https://api.link.com',
              credential_endpoint: 'https://api.link.com/identity/credentials',
            })
          : jsonResponse({
              credential: 'issuer-jwt~',
              issuer: 'https://attacker.example',
              expires_at: '2026-08-25T00:00:00Z',
            }),
    );
    const resource = new IdentityCredentialsResource({
      accessToken: 'access-token',
      fetch: fetchMock,
    });

    await expect(
      resource.issue({ cnf: { jwk: PUBLIC_JWK } }),
    ).rejects.toBeInstanceOf(LinkResponseError);
  });

  it('sends only public JWK members', async () => {
    const fetchMock = vi.fn(
      async (input: RequestInfo | URL, init?: RequestInit) => {
        if (String(input).endsWith('/.well-known/aap-issuer')) {
          return jsonResponse({
            issuer: 'https://api.link.com',
            credential_endpoint: 'https://api.link.com/identity/credentials',
          });
        }
        expect(JSON.parse(String(init?.body))).toEqual({
          cnf: { jwk: PUBLIC_JWK },
        });
        return jsonResponse({
          credential: 'issuer-jwt~',
          issuer: 'https://api.link.com',
          expires_at: '2026-08-25T00:00:00Z',
        });
      },
    );
    const resource = new IdentityCredentialsResource({
      accessToken: 'access-token',
      fetch: fetchMock,
    });

    await expect(
      resource.issue({
        cnf: { jwk: { ...PUBLIC_JWK, d: 'private' } as never },
      }),
    ).resolves.toMatchObject({ issuer: 'https://api.link.com' });
    expect(fetchMock).toHaveBeenCalledTimes(2);
  });

  it('refreshes LinkOptions authentication after a credential 401', async () => {
    const fetchMock = vi.fn(
      async (input: RequestInfo | URL, _init?: RequestInit) =>
        String(input).endsWith('/.well-known/aap-issuer')
          ? jsonResponse({
              issuer: 'https://api.link.com',
              credential_endpoint: 'https://api.link.com/identity/credentials',
            })
          : jsonResponse({ error: 'unauthorized' }, 401),
    );
    const getAccessToken = vi.fn(
      ({ forceRefresh }: { forceRefresh?: boolean } = {}) =>
        forceRefresh ? 'refreshed-token' : 'initial-token',
    );
    const resource = new IdentityCredentialsResource({
      getAccessToken,
      fetch: fetchMock,
    });

    await expect(resource.issue({ cnf: { jwk: PUBLIC_JWK } })).rejects.toThrow(
      'Failed to issue identity credential (401)',
    );
    expect(getAccessToken).toHaveBeenNthCalledWith(1);
    expect(getAccessToken).toHaveBeenNthCalledWith(2, { forceRefresh: true });
    expect(fetchMock.mock.calls[1]?.[1]).toMatchObject({
      headers: expect.objectContaining({
        Authorization: 'Bearer initial-token',
      }),
    });
    expect(fetchMock.mock.calls[2]?.[1]).toMatchObject({
      headers: expect.objectContaining({
        Authorization: 'Bearer refreshed-token',
      }),
    });
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { LinkApiError, LinkSdkError } from '@/errors';
import { WebBotAuthResource } from '@/resources/web-bot-auth';
import type { WebBotAuthBlock } from '@/types/index';

const mockFetch = vi.fn();
const getAccessToken = vi.fn();

function mockFetchResponse(status: number, body: Record<string, unknown>) {
  mockFetch.mockResolvedValue({
    status,
    text: async () => JSON.stringify(body),
  });
}

const validUrl = 'https://wine-merchant.com/products';

const webBotAuthBlock: WebBotAuthBlock = {
  signature: 'sig1=:stub_sig:',
  signature_input:
    'sig1=("@authority" "signature-agent");created=1715400000;keyid="stub_keyid";alg="ed25519";expires=1715400600;tag="web-bot-auth"',
  signature_agent:
    'https://api.link.com/.well-known/http-message-signatures-directory',
  authority: 'wine-merchant.com',
  expires_at: '2099-12-31T23:59:59Z',
};

const credentialsResponse = {
  web_bot_auth: webBotAuthBlock,
};

describe('WebBotAuthResource', () => {
  let resource: WebBotAuthResource;

  beforeEach(() => {
    vi.stubGlobal('fetch', mockFetch);
    vi.clearAllMocks();
    getAccessToken.mockResolvedValue('test_token');
    resource = new WebBotAuthResource({ getAccessToken });
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  describe('signUrl', () => {
    it('sends POST to /web_bot_auth/sign with JSON body and Bearer auth', async () => {
      mockFetchResponse(200, credentialsResponse);

      await resource.signUrl(validUrl);

      expect(mockFetch).toHaveBeenCalledOnce();
      const [url, opts] = mockFetch.mock.calls[0]!;
      expect(url).toBe('https://api.link.com/web_bot_auth/sign');
      expect(opts.method).toBe('POST');
      expect(opts.headers['Content-Type']).toBe('application/json');
      expect(opts.headers.Authorization).toBe('Bearer test_token');
      expect(JSON.parse(opts.body)).toEqual({ url: validUrl });
    });

    it('returns the web_bot_auth block on success', async () => {
      mockFetchResponse(200, credentialsResponse);

      const result = await resource.signUrl(validUrl);

      expect(result).toEqual(webBotAuthBlock);
    });

    it('caches result per authority and skips re-fetch for same hostname', async () => {
      mockFetchResponse(200, credentialsResponse);

      const first = await resource.signUrl(validUrl);
      const second = await resource.signUrl(
        'https://wine-merchant.com/other-page',
      );

      expect(mockFetch).toHaveBeenCalledOnce();
      expect(second).toEqual(first);
    });

    it('does not share cache across different authorities', async () => {
      mockFetchResponse(200, credentialsResponse);
      await resource.signUrl(validUrl);

      mockFetchResponse(200, credentialsResponse);
      await resource.signUrl('https://other-merchant.com/page');

      expect(mockFetch).toHaveBeenCalledTimes(2);
    });

    it('re-fetches when cached entry expires within the 30s buffer', async () => {
      const nearlyExpiredBlock: WebBotAuthBlock = {
        ...webBotAuthBlock,
        expires_at: new Date(Date.now() + 20_000).toISOString(),
      };
      mockFetchResponse(200, {
        ...credentialsResponse,
        web_bot_auth: nearlyExpiredBlock,
      });

      await resource.signUrl(validUrl);

      mockFetchResponse(200, credentialsResponse);
      await resource.signUrl(validUrl);

      expect(mockFetch).toHaveBeenCalledTimes(2);
    });

    it('does not re-fetch when cached entry is still fresh', async () => {
      mockFetchResponse(200, credentialsResponse);

      await resource.signUrl(validUrl);
      await resource.signUrl(validUrl);

      expect(mockFetch).toHaveBeenCalledOnce();
    });

    it('retries with refreshed token on 401', async () => {
      mockFetch
        .mockResolvedValueOnce({ status: 401, text: async () => '{}' })
        .mockResolvedValueOnce({
          status: 200,
          text: async () => JSON.stringify(credentialsResponse),
        });
      getAccessToken
        .mockResolvedValueOnce('expired_token')
        .mockResolvedValueOnce('fresh_token');

      const result = await resource.signUrl(validUrl);

      expect(mockFetch).toHaveBeenCalledTimes(2);
      const [, secondOpts] = mockFetch.mock.calls[1]!;
      expect(secondOpts.headers.Authorization).toBe('Bearer fresh_token');
      expect(result).toEqual(webBotAuthBlock);
    });

    it('throws LinkApiError on HTTP error', async () => {
      mockFetchResponse(422, { error: 'Invalid URL' });

      const err = await resource.signUrl(validUrl).catch((e) => e);
      expect(err).toBeInstanceOf(LinkApiError);
      expect(err.message).toMatch('Failed to get web bot auth headers (422)');
    });

    it('extracts message from nested error object instead of [object Object]', async () => {
      mockFetchResponse(400, { error: { message: 'signature failed' } });

      const err = await resource.signUrl(validUrl).catch((e) => e);
      expect(err).toBeInstanceOf(LinkApiError);
      expect(err.message).toBe(
        'Failed to get web bot auth headers (400): signature failed',
      );
    });

    it('throws LinkSdkError when expires_at is malformed', async () => {
      mockFetchResponse(200, {
        ...credentialsResponse,
        web_bot_auth: { ...webBotAuthBlock, expires_at: 'not-a-date' },
      });

      const err = await resource.signUrl(validUrl).catch((e) => e);
      expect(err).toBeInstanceOf(LinkSdkError);
      expect(err.message).toMatch('invalid expires_at');
    });

    it('throws LinkSdkError when response is missing web_bot_auth block', async () => {
      mockFetchResponse(200, { identity_token: 'tok_test123' });

      const err = await resource.signUrl(validUrl).catch((e) => e);
      expect(err).toBeInstanceOf(LinkSdkError);
      expect(err.code).toBe('invalid_response');
    });

    it('throws when access token is unavailable', async () => {
      getAccessToken.mockRejectedValueOnce(new Error('Missing access token'));

      await expect(resource.signUrl(validUrl)).rejects.toThrow(
        'Missing access token',
      );
    });

    it('throws LinkSdkError on invalid URL', async () => {
      const err = await resource.signUrl('not-a-url').catch((e) => e);
      expect(err).toBeInstanceOf(LinkSdkError);
      expect(err.message).toMatch('Invalid URL');
    });
  });
});

# Test an Agent Identity integration

See the [package README](../README.md) for setup.

The SDK ships `LinkFixture` and `CredentialFixture` under `@stripe/agent-identity/testing`. They use real cryptographic signatures and local issuer responses, so tests can exercise the full verifier without contacting Link.

## Check bearer tokens

```ts
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { LinkVerifier } from '@stripe/agent-identity';
import { LinkFixture } from '@stripe/agent-identity/testing';

test('accepts an issued token and rejects a forged token', async () => {
  const link = await LinkFixture.create();
  const verifier = new LinkVerifier({
    origin: 'https://shop.example',
    fetchImpl: link.fetchImpl(),
  });

  const token = await link.mint();
  assert.equal((await verifier.verifyAttestation(token.authorization)).valid, true);

  const forged = await link.mint({ corruptAuthenticator: true });
  const result = await verifier.verifyAttestation(forged.authorization);
  assert.equal(result.valid, false);
  if (!result.valid) {
    assert.equal(result.failures[0]?.code, 'invalid_private_token');
  }
});
```

The fixture signs a token authenticator directly. It exercises redemption verification, not the blinding and unblinding performed during issuance.

Repository maintainers can also run the [wallet integration test](../README.md#development). It uses the built wallet to blind requests, unblind real issuer signatures, save and pop tokens, and sign presentations with its persisted holder key. It checks selective disclosure, audience and nonce rejection, and the executable event-registration example. The issuer is local and the wallet uses temporary storage; no Link account is required.

## Check identity claims

```ts
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { LinkVerifier, clearJwksCache } from '@stripe/agent-identity';
import {
  LinkFixture, CredentialFixture, combineFetch,
} from '@stripe/agent-identity/testing';

test('verifies a presentation without enforcing replay policy', async () => {
  clearJwksCache();
  const link = await LinkFixture.create();
  const credential = await CredentialFixture.create({
    issuerUrl: link.issuer,
    claims: { email: 'ada@example.com' },
  });
  const verifier = new LinkVerifier({
    origin: 'https://shop.example',
    fetchImpl: combineFetch(link.fetchImpl(), credential.fetchImpl()),
  });
  const challenge = await verifier.claimsChallenge({ claims: ['email'] });
  const presentation = await credential.present({
    aud: challenge.body.aud,
    nonce: challenge.nonce,
    disclose: ['email'],
  });
  const options = { nonce: challenge.nonce, requiredClaims: ['email'] };

  assert.equal((await verifier.verifyClaims(presentation, options)).valid, true);
  assert.equal((await verifier.verifyClaims(presentation, options)).valid, true);
});
```

Credential signing keys are cached process-wide by issuer JWKS URL. Call `clearJwksCache()` between tests that create different keys for the same issuer. Avoid running those fixture sets concurrently in the same process.

Test application replay policy separately. If an interaction may succeed only once, cover concurrent retries against the application state that atomically completes the interaction. Do not expect the SDK to make one verification fail.

## Test your HTTP boundary

Use a real HTTP listener in addition to SDK-level tests. The framework controls repeated headers, request bodies, and response formatting.

| Case | Expected behavior |
| --- | --- |
| Missing credential | `401` with the appropriate challenge |
| Concurrent first requests with valid attestations | All share issuer discovery; no false credential rejections |
| Stale issuer keys during outage backoff | `issuer_unavailable`; never accept keys beyond configured freshness |
| Nonnumeric presentation signing time or inherited claim names | Rejection; freshness and required claims use validated values |
| Forged token or wrong audience | Rejection before the protected operation |
| Missing required claims | Rejection without mutating application state |
| Two SDK verifications with the same valid presentation and expected nonce | Both succeed; replay policy belongs to the application |
| Two application requests for a single-use interaction | Application state permits exactly one operation |
| Different sessions | A presentation cannot answer another session's expected nonce |
| Duplicate credential fields | Rejection before the framework loses duplicate information |
| Invalid or oversized JSON | Your framework's normal body validation applies |
| Issuer or application state unavailable | `503`; no protected operation |

## Control time

The `now` option returns Unix time in seconds. Fixture credential expiry and presentation `iat` must agree with your injected time. Your application controls the clock used for interaction expiry.

The following excerpt assumes an existing `fetchImpl` and an `assert` import:

```ts
let now = Math.floor(Date.now() / 1000);
const verifier = new LinkVerifier({
  origin: 'https://shop.example',
  fetchImpl,
  now: () => now,
});

const challenge = await verifier.claimsChallenge({
  claims: ['email'],
  nonceTtlSeconds: 2,
});
now += 2;
assert.equal(challenge.expiresAt, now);
```

`nonceTtlSeconds` controls the returned `expiresAt` metadata. The SDK does not enforce that expiry; test your application's expiration behavior where it stores the interaction.

package link

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestUpdatePaymentMethod(t *testing.T) {
	var method, requestURI, contentType string
	var body map[string]any
	server := httptest.NewServer(http.HandlerFunc(func(response http.ResponseWriter, request *http.Request) {
		method = request.Method
		requestURI = request.RequestURI
		contentType = request.Header.Get("Content-Type")
		if err := json.NewDecoder(request.Body).Decode(&body); err != nil {
			t.Fatal(err)
		}
		response.Header().Set("Content-Type", "application/json")
		_, _ = response.Write([]byte(`{"id":"pd/../other","type":"CARD","is_default":true,"name":"Visa","nickname":"Work card"}`))
	}))
	defer server.Close()

	client, err := NewClient(Options{AccessToken: "token", APIBaseURL: server.URL})
	if err != nil {
		t.Fatal(err)
	}
	result, err := client.PaymentMethods.Update(context.Background(), "pd/../other", UpdatePaymentMethodParams{Nickname: "Work card"})
	if err != nil {
		t.Fatal(err)
	}
	if method != http.MethodPost || requestURI != "/payment-details/pd%2F..%2Fother" {
		t.Fatalf("got %s %s", method, requestURI)
	}
	if contentType != "application/json" || body["nickname"] != "Work card" {
		t.Fatalf("got content type %q and body %#v", contentType, body)
	}
	if result.Nickname == nil || *result.Nickname != "Work card" {
		t.Fatalf("got %#v", result)
	}
}

func TestUpdatePaymentMethodPreservesEmptyNickname(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(response http.ResponseWriter, request *http.Request) {
		var body map[string]any
		if err := json.NewDecoder(request.Body).Decode(&body); err != nil {
			t.Fatal(err)
		}
		if value, ok := body["nickname"]; !ok || value != "" {
			t.Fatalf("got body %#v", body)
		}
		_, _ = response.Write([]byte(`{"id":"pd_1","type":"CARD","is_default":true,"name":"Visa","nickname":null}`))
	}))
	defer server.Close()
	client, _ := NewClient(Options{AccessToken: "token", APIBaseURL: server.URL})
	result, err := client.PaymentMethods.Update(context.Background(), "pd_1", UpdatePaymentMethodParams{Nickname: ""})
	if err != nil || result.Nickname != nil {
		t.Fatalf("result %#v, error %v", result, err)
	}
}

func TestUpdatePaymentMethodErrors(t *testing.T) {
	t.Run("nested API error", func(t *testing.T) {
		server := httptest.NewServer(http.HandlerFunc(func(response http.ResponseWriter, _ *http.Request) {
			response.WriteHeader(http.StatusForbidden)
			_, _ = response.Write([]byte(`{"error":{"message":"feature unavailable"}}`))
		}))
		defer server.Close()
		client, _ := NewClient(Options{AccessToken: "token", APIBaseURL: server.URL})
		_, err := client.PaymentMethods.Update(context.Background(), "pd_1", UpdatePaymentMethodParams{Nickname: "Work"})
		var apiError *LinkAPIError
		if !errors.As(err, &apiError) || apiError.Status != http.StatusForbidden || !strings.Contains(err.Error(), "feature unavailable") {
			t.Fatalf("got %#v", err)
		}
	})

	t.Run("malformed success", func(t *testing.T) {
		server := httptest.NewServer(http.HandlerFunc(func(response http.ResponseWriter, _ *http.Request) {
			_, _ = response.Write([]byte(`{"id":123}`))
		}))
		defer server.Close()
		client, _ := NewClient(Options{AccessToken: "token", APIBaseURL: server.URL})
		_, err := client.PaymentMethods.Update(context.Background(), "pd_1", UpdatePaymentMethodParams{Nickname: "Work"})
		var responseError *LinkResponseError
		if !errors.As(err, &responseError) {
			t.Fatalf("got %#v", err)
		}
	})
}

func TestUpdatePaymentMethodRetriesProvider401(t *testing.T) {
	requests := 0
	providerCalls := 0
	server := httptest.NewServer(http.HandlerFunc(func(response http.ResponseWriter, request *http.Request) {
		requests++
		if requests == 1 {
			response.WriteHeader(http.StatusUnauthorized)
			return
		}
		_, _ = response.Write([]byte(`{"id":"pd_1","type":"CARD","is_default":true,"name":"Visa","nickname":"Work"}`))
	}))
	defer server.Close()
	client, _ := NewClient(Options{
		APIBaseURL: server.URL,
		GetAccessToken: func(_ context.Context, options GetAccessTokenOptions) (string, error) {
			providerCalls++
			if providerCalls == 2 && !options.ForceRefresh {
				t.Fatal("second provider call did not force refresh")
			}
			return "token", nil
		},
	})
	if _, err := client.PaymentMethods.Update(context.Background(), "pd_1", UpdatePaymentMethodParams{Nickname: "Work"}); err != nil {
		t.Fatal(err)
	}
	if requests != 2 || providerCalls != 2 {
		t.Fatalf("got %d requests and %d provider calls", requests, providerCalls)
	}
}

import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import Conf from 'conf';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { type PendingDeviceAuth, Storage } from '../storage';
import type { AuthTokens } from '../types';

interface LegacyStorageSchema {
  auth: AuthTokens | null;
  pendingDeviceAuth: PendingDeviceAuth | null;
}

const describePosix = process.platform === 'win32' ? describe.skip : describe;

describePosix('CLI auth storage', () => {
  let tmpDir: string;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'link-cli-storage-test-'));
  });

  afterEach(() => {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  it('reads credentials written by the pre-branch-4 storage', () => {
    const tokens: AuthTokens = {
      access_token: 'at_existing',
      refresh_token: 'rt_existing',
      expires_in: 3600,
      expires_at: Date.now() + 3_600_000,
      token_type: 'Bearer',
      scope: 'userinfo:read payment_methods.agentic',
    };
    const pendingDeviceAuth: PendingDeviceAuth = {
      device_code: 'dc_existing',
      interval: 5,
      expires_at: Date.now() + 60_000,
      verification_url: 'https://login.link.com/device',
      phrase: 'existing-phrase',
    };
    const legacyStorage = new Conf<LegacyStorageSchema>({
      projectName: 'link-cli',
      cwd: tmpDir,
      configFileMode: 0o600,
      defaults: { auth: null, pendingDeviceAuth: null },
    });
    legacyStorage.set('auth', tokens);
    legacyStorage.set('pendingDeviceAuth', pendingDeviceAuth);

    const storage = new Storage({ cwd: tmpDir });

    expect(storage.getPath()).toBe(legacyStorage.path);
    expect(storage.getTokens()).toEqual(tokens);
    expect(storage.getPendingDeviceAuth()).toEqual(pendingDeviceAuth);
  });

  it('implements the SDK token-storage contract', () => {
    const storage = new Storage({ cwd: tmpDir });

    storage.setTokens({
      access_token: 'at_test',
      refresh_token: 'rt_test',
      expires_in: 3600,
      token_type: 'Bearer',
    });

    expect(storage.getTokens()?.access_token).toBe('at_test');
    expect(storage.getTokens()?.expires_at).toBeTypeOf('number');
    storage.clearTokens();
    expect(storage.getTokens()).toBeNull();
  });

  it('writes credentials with mode 0o600', () => {
    const storage = new Storage({ cwd: tmpDir });

    storage.setTokens({
      access_token: 'at_test',
      refresh_token: 'rt_test',
      expires_in: 3600,
      token_type: 'Bearer',
    });

    expect(fs.statSync(storage.getPath()).mode & 0o777).toBe(0o600);
  });

  it('repairs an existing config file with broader permissions', () => {
    const seedStorage = new Storage({ cwd: tmpDir });
    seedStorage.setTokens({
      access_token: 'at_seed',
      refresh_token: 'rt_seed',
      expires_in: 3600,
      token_type: 'Bearer',
    });
    const configPath = seedStorage.getPath();
    fs.chmodSync(configPath, 0o644);

    const upgradedStorage = new Storage({ cwd: tmpDir });
    upgradedStorage.setTokens({
      access_token: 'at_after_upgrade',
      refresh_token: 'rt_after_upgrade',
      expires_in: 3600,
      token_type: 'Bearer',
    });

    expect(fs.statSync(configPath).mode & 0o777).toBe(0o600);
  });

  it('uses an explicit credential path in preference to cwd', () => {
    const customPath = path.join(tmpDir, 'custom-creds.json');
    const otherDir = fs.mkdtempSync(path.join(os.tmpdir(), 'link-cli-other-'));
    const storage = new Storage({ configPath: customPath, cwd: otherDir });

    storage.setTokens({
      access_token: 'at_custom',
      refresh_token: 'rt_custom',
      expires_in: 3600,
      token_type: 'Bearer',
    });

    expect(storage.getPath()).toBe(customPath);
    expect(storage.getTokens()?.access_token).toBe('at_custom');
    expect(fs.statSync(customPath).mode & 0o777).toBe(0o600);
    fs.rmSync(otherDir, { recursive: true, force: true });
  });

  it('keeps pending CLI workflow state out of the SDK token contract', () => {
    const storage = new Storage({ cwd: tmpDir });

    storage.setPendingDeviceAuth({
      device_code: 'dc_test_must_not_leak',
      interval: 5,
      expires_at: Date.now() + 60_000,
      verification_url: 'https://login.link.com/device',
      phrase: 'test-phrase',
      replaces_existing_session: true,
    });

    expect(storage.getPendingDeviceAuth()?.replaces_existing_session).toBe(
      true,
    );
    expect(fs.statSync(storage.getPath()).mode & 0o777).toBe(0o600);
  });
});

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import type { IdentityCredentialIssueResult } from '../issue';
import { writeIdentityCredentialArtifact } from '../storage';

const artifact: IdentityCredentialIssueResult = {
  version: 1,
  credential: 'credential',
  issuer: 'https://api.link.com',
  expires_at: '2026-09-18T00:00:00Z',
  holder: {
    jwk: { kty: 'OKP', crv: 'Ed25519', x: 'public-key' },
    thumbprint: 'thumbprint',
    path: '/path/to/holder-key.jwk',
    created: true,
  },
};

describe('identity credential artifact storage', () => {
  let tmpDir: string;

  beforeEach(async () => {
    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'link-credentials-'));
    vi.spyOn(os, 'homedir').mockReturnValue(tmpDir);
  });

  afterEach(async () => {
    vi.restoreAllMocks();
    await fs.rm(tmpDir, { recursive: true, force: true });
  });

  it('atomically replaces the current artifact in a private directory', async () => {
    const directory = path.join(tmpDir, '.link-cli', 'identity', 'credentials');
    const first = await writeIdentityCredentialArtifact(artifact);
    const replacement = { ...artifact, credential: 'replacement' };
    const second = await writeIdentityCredentialArtifact(replacement);

    expect(first).toBe(second);
    expect(path.basename(first)).toBe('current.json');
    expect(path.dirname(first)).toBe(directory);
    expect(JSON.parse(await fs.readFile(first, 'utf8'))).toEqual(replacement);
    expect(await fs.readdir(directory)).toEqual(['current.json']);
    expect((await fs.stat(directory)).mode & 0o777).toBe(0o700);
    expect((await fs.stat(first)).mode & 0o777).toBe(0o600);
  });

  it('rejects a symbolic-link output directory', async () => {
    const target = path.join(tmpDir, 'target');
    const directory = path.join(tmpDir, '.link-cli', 'identity', 'credentials');
    await fs.mkdir(target);
    await fs.mkdir(path.dirname(directory), { recursive: true });
    await fs.symlink(target, directory);

    await expect(writeIdentityCredentialArtifact(artifact)).rejects.toThrow(
      'CREDENTIAL_OUTPUT_DIRECTORY_INVALID',
    );
    expect(await fs.readdir(target)).toEqual([]);
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { LinkApiError } from '@/errors';
import { PaymentMethodsResource } from '@/resources/payment-methods';

const mockFetch = vi.fn();
const getAccessToken = vi.fn();

function mockFetchResponse(status: number, body: Record<string, unknown>) {
  mockFetch.mockResolvedValue({
    status,
    text: async () => JSON.stringify(body),
  });
}

describe('PaymentMethodsResource', () => {
  let repo: PaymentMethodsResource;

  beforeEach(() => {
    vi.stubGlobal('fetch', mockFetch);
    vi.clearAllMocks();
    getAccessToken.mockResolvedValue('test_token');
    repo = new PaymentMethodsResource({ getAccessToken });
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it('lists payment methods from the expected endpoint', async () => {
    mockFetchResponse(200, {
      payment_details: [
        {
          id: 'pm_123',
          type: 'card',
          is_default: true,
          card_details: {
            brand: 'visa',
            last4: '4242',
            exp_month: 12,
            exp_year: 2028,
          },
          name: 'Visa Credit',
          nickname: 'Home Credit',
        },
      ],
    });

    const result = await repo.list();

    expect(mockFetch).toHaveBeenCalledOnce();
    const [url, opts] = mockFetch.mock.calls[0]!;
    expect(url).toBe('https://api.link.com/payment-details');
    expect(opts.method).toBe('GET');
    expect(opts.headers.Authorization).toBe('Bearer test_token');
    expect(result).toEqual([
      {
        id: 'pm_123',
        type: 'card',
        is_default: true,
        card_details: {
          brand: 'visa',
          last4: '4242',
          exp_month: 12,
          exp_year: 2028,
        },
        name: 'Visa Credit',
        nickname: 'Home Credit',
      },
    ]);
  });

  it('lists Link balance details when available', async () => {
    mockFetchResponse(200, {
      payment_details: [
        {
          id: 'csmrpd_balance',
          type: 'BALANCE',
          is_default: false,
          name: 'Link balance',
          card_details: null,
          bank_account_details: null,
          balance_details: {
            available_balance: { amount: 1250, currency: 'usd' },
          },
        },
      ],
      unavailable_count: 0,
    });

    await expect(repo.list()).resolves.toEqual([
      {
        id: 'csmrpd_balance',
        type: 'BALANCE',
        is_default: false,
        name: 'Link balance',
        card_details: null,
        bank_account_details: null,
        balance_details: {
          available_balance: { amount: 1250, currency: 'usd' },
        },
      },
    ]);
  });

  it('preserves balance details when the available balance is unknown', async () => {
    mockFetchResponse(200, {
      payment_details: [
        {
          id: 'csmrpd_balance',
          type: 'BALANCE',
          is_default: false,
          name: 'Link balance',
          balance_details: {},
        },
      ],
      unavailable_count: 0,
    });

    const result = await repo.list();

    expect(result[0]?.balance_details).toEqual({});
  });

  it('retrieves a payment method from the expected endpoint', async () => {
    mockFetchResponse(200, {
      id: 'pd_123',
      type: 'CARD',
      is_default: true,
      name: 'Visa',
      card_details: {
        brand: 'visa',
        last4: '4242',
        exp_month: 12,
        exp_year: 2028,
      },
    });

    const result = await repo.retrieve('pd_123');

    expect(mockFetch).toHaveBeenCalledOnce();
    const [url, opts] = mockFetch.mock.calls[0]!;
    expect(url).toBe('https://api.link.com/payment-details/pd_123');
    expect(opts.method).toBe('GET');
    expect(opts.headers.Authorization).toBe('Bearer test_token');
    expect(result).toMatchObject({ id: 'pd_123', name: 'Visa' });
  });

  it('returns null when a payment method is not found', async () => {
    mockFetchResponse(404, {
      error: { message: 'Payment details not found' },
    });

    await expect(repo.retrieve('pd_missing')).resolves.toBeNull();
  });

  it('updates a payment-method nickname', async () => {
    mockFetchResponse(200, {
      id: 'pd_123',
      type: 'CARD',
      is_default: true,
      name: 'Visa',
      nickname: 'Work card',
    });

    const result = await repo.update('pd_123', { nickname: 'Work card' });

    const [url, opts] = mockFetch.mock.calls[0]!;
    expect(url).toBe('https://api.link.com/payment-details/pd_123');
    expect(opts).toMatchObject({
      method: 'POST',
      headers: {
        Authorization: 'Bearer test_token',
        'Content-Type': 'application/json',
      },
      body: '{"nickname":"Work card"}',
    });
    expect(result).toMatchObject({ id: 'pd_123', nickname: 'Work card' });
  });

  it('preserves an empty nickname when clearing', async () => {
    mockFetchResponse(200, {
      id: 'pd_123',
      type: 'CARD',
      is_default: true,
      name: 'Visa',
      nickname: null,
    });

    await expect(
      repo.update('pd_123', { nickname: '' }),
    ).resolves.toMatchObject({
      nickname: null,
    });
    expect(mockFetch.mock.calls[0]![1].body).toBe('{"nickname":""}');
  });

  it('encodes the payment method ID in the update path', async () => {
    mockFetchResponse(200, {
      id: 'pd/../other',
      type: 'CARD',
      is_default: false,
      name: 'Visa',
    });

    await repo.update('pd/../other', { nickname: 'Work' });

    expect(mockFetch.mock.calls[0]![0]).toBe(
      'https://api.link.com/payment-details/pd%2F..%2Fother',
    );
  });

  it.each([
    [400, 'nickname is too long'],
    [403, 'Nickname updates are unavailable'],
    [404, 'Payment method not found'],
  ])('throws a typed update error for %s', async (status, message) => {
    mockFetchResponse(status, { error: { message } });

    const error = await repo
      .update('pd_123', { nickname: 'Work' })
      .catch((e) => e);
    expect(error).toBeInstanceOf(LinkApiError);
    expect(error).toMatchObject({ status });
    expect(error.message).toContain(message);
  });

  it('rejects malformed successful update responses', async () => {
    mockFetchResponse(200, { id: 123 });

    const error = await repo
      .update('pd_123', { nickname: 'Work' })
      .catch((e) => e);
    expect(error.code).toBe('invalid_response');
  });

  it('refreshes and retries an update once on 401', async () => {
    mockFetch
      .mockResolvedValueOnce({
        status: 401,
        text: async () => JSON.stringify({ error: 'expired_token' }),
      })
      .mockResolvedValueOnce({
        status: 200,
        text: async () =>
          JSON.stringify({
            id: 'pd_123',
            type: 'CARD',
            is_default: true,
            name: 'Visa',
            nickname: 'Work',
          }),
      });
    getAccessToken
      .mockResolvedValueOnce('test_token')
      .mockResolvedValueOnce('fresh_token');

    await repo.update('pd_123', { nickname: 'Work' });

    expect(mockFetch).toHaveBeenCalledTimes(2);
    expect(mockFetch.mock.calls[1]![1].headers.Authorization).toBe(
      'Bearer fresh_token',
    );
  });

  it('does not retry a fixed-token update after a 401', async () => {
    repo = new PaymentMethodsResource({ accessToken: 'fixed_token' });
    mockFetchResponse(401, { error: 'expired_token' });

    await expect(repo.update('pd_123', { nickname: 'Work' })).rejects.toThrow(
      'Failed to update payment method (401): expired_token',
    );
    expect(mockFetch).toHaveBeenCalledOnce();
  });

  it('encodes the payment method ID in the retrieve path', async () => {
    mockFetchResponse(404, {
      error: { message: 'Payment details not found' },
    });

    await repo.retrieve('pd/../other');

    expect(mockFetch.mock.calls[0]![0]).toBe(
      'https://api.link.com/payment-details/pd%2F..%2Fother',
    );
  });

  it('throws non-404 retrieve errors', async () => {
    mockFetchResponse(500, { error: 'internal_error' });

    await expect(repo.retrieve('pd_123')).rejects.toThrow(
      'Failed to retrieve payment method (500): internal_error',
    );
  });

  it('refreshes the token and retries once on 401', async () => {
    mockFetch
      .mockResolvedValueOnce({
        status: 401,
        text: async () => JSON.stringify({ error: 'expired_token' }),
      })
      .mockResolvedValueOnce({
        status: 200,
        text: async () => JSON.stringify({ payment_details: [] }),
      });
    getAccessToken
      .mockResolvedValueOnce('test_token')
      .mockResolvedValueOnce('fresh_token');

    const result = await repo.list();

    expect(result).toEqual([]);
    expect(getAccessToken).toHaveBeenNthCalledWith(1);
    expect(getAccessToken).toHaveBeenNthCalledWith(2, { forceRefresh: true });
    expect(mockFetch).toHaveBeenCalledTimes(2);
    expect(mockFetch.mock.calls[1]![1].headers.Authorization).toBe(
      'Bearer fresh_token',
    );
  });

  it('does not retry a 401 when configured with a fixed access token', async () => {
    repo = new PaymentMethodsResource({ accessToken: 'fixed_token' });
    mockFetchResponse(401, { error: 'expired_token' });

    await expect(repo.list()).rejects.toThrow(
      'Failed to list payment methods (401): expired_token',
    );
    expect(mockFetch).toHaveBeenCalledOnce();
  });

  it('never logs tokens or response bodies in verbose mode', async () => {
    const debug = vi.fn();
    repo = new PaymentMethodsResource({
      getAccessToken,
      verbose: true,
      logger: { debug },
    });
    mockFetchResponse(200, {
      payment_details: [
        {
          id: 'pm_secret',
          type: 'card',
          is_default: true,
          name: 'Visa Credit',
          nickname: 'Home Credit',
        },
      ],
    });

    await repo.list();

    const output = debug.mock.calls.flat().join('\n');
    expect(output).not.toContain('test_token');
    expect(output).not.toContain('pm_secret');
  });

  it('rejects malformed successful responses', async () => {
    mockFetchResponse(200, {
      payment_details: [
        {
          id: 123,
          type: 'card',
          is_default: true,
          name: 'Visa Credit',
          nickname: 'Home Credit',
        },
      ],
    });

    const error = await repo.list().catch((cause) => cause);
    expect(error.code).toBe('invalid_response');
  });

  it('throws API errors with the response message', async () => {
    mockFetchResponse(403, { message: 'Forbidden' });

    await expect(repo.list()).rejects.toThrow(
      'Failed to list payment methods (403): Forbidden',
    );
  });

  it('extracts message from nested error object instead of [object Object]', async () => {
    mockFetchResponse(400, { error: { message: 'card not supported' } });

    await expect(repo.list()).rejects.toThrow(
      'Failed to list payment methods (400): card not supported',
    );
  });

  it('throws when no access token is available', async () => {
    getAccessToken.mockRejectedValueOnce(new Error('Missing access token'));

    await expect(repo.list()).rejects.toThrow('Missing access token');
  });
});

