package link

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/url"
	"strconv"
)

// TransactionsResource provides transaction operations.
type TransactionsResource struct {
	base *baseResource
}

// List returns a page of transactions.
func (r *TransactionsResource) List(ctx context.Context, params *ListTransactionsParams) (*TransactionsPage, error) {
	endpoint, err := url.Parse(r.base.baseURL + "/transactions")
	if err != nil {
		return nil, newConfigurationError("Invalid transactions URL: " + err.Error())
	}
	query := endpoint.Query()
	if params != nil {
		if params.Limit != nil {
			query.Set("limit", strconv.FormatInt(*params.Limit, 10))
		}
		if params.StartingAfter != nil {
			query.Set("starting_after", *params.StartingAfter)
		}
		if params.EndingBefore != nil {
			query.Set("ending_before", *params.EndingBefore)
		}
		if params.StartDate != nil {
			query.Set("date_start", *params.StartDate)
		}
		if params.EndDate != nil {
			query.Set("date_end", *params.EndDate)
		}
		if params.Category != nil {
			query.Set("category", *params.Category)
		}
		if params.Origin != nil {
			query.Set("origin", string(*params.Origin))
		}
		for _, source := range params.Sources {
			query.Add("sources[]", source)
		}
	}
	endpoint.RawQuery = query.Encode()
	response, err := r.base.fetch(ctx, http.MethodGet, endpoint.String(), nil, nil)
	if err != nil {
		return nil, err
	}
	if response.status < 200 || response.status >= 300 {
		return nil, newAPIError("list transactions", response.status, response.data, response.rawBody)
	}
	data := bytes.TrimSpace([]byte(response.rawBody))
	var page TransactionsPage
	if len(data) > 0 && data[0] == '[' {
		if err := json.Unmarshal(data, &page.Data); err != nil {
			return nil, newResponseError("list transactions", response.status, err)
		}
	} else {
		if err := decodeResponse("list transactions", response, &page); err != nil {
			return nil, err
		}
	}
	return &page, nil
}

package link

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"sync"
	"time"
)

const webBotAuthExpiryBuffer = 30 * time.Second

type webBotAuthCacheEntry struct {
	block     WebBotAuthBlock
	expiresAt time.Time
}

// WebBotAuthResource signs merchant URLs for Web Bot Auth.
type WebBotAuthResource struct {
	base  *baseResource
	mu    sync.RWMutex
	cache map[string]webBotAuthCacheEntry
	now   func() time.Time
}

func newWebBotAuthResource(base *baseResource) *WebBotAuthResource {
	return &WebBotAuthResource{
		base:  base,
		cache: make(map[string]webBotAuthCacheEntry),
		now:   time.Now,
	}
}

// SignURL returns signing material for the URL's authority. Fresh credentials
// are cached by hostname until 30 seconds before expiration.
func (r *WebBotAuthResource) SignURL(ctx context.Context, rawURL string) (*WebBotAuthBlock, error) {
	parsed, err := url.Parse(rawURL)
	if err != nil || parsed.Scheme == "" || parsed.Hostname() == "" {
		if err == nil {
			err = fmt.Errorf("URL must be absolute")
		}
		return nil, newSDKError("Invalid URL: "+rawURL, err)
	}
	authority := parsed.Hostname()

	r.mu.RLock()
	cached, ok := r.cache[authority]
	r.mu.RUnlock()
	if ok && r.now().Before(cached.expiresAt.Add(-webBotAuthExpiryBuffer)) {
		block := cached.block
		return &block, nil
	}

	var envelope struct {
		WebBotAuth WebBotAuthBlock `json:"web_bot_auth"`
	}
	requestBody, err := json.Marshal(struct {
		URL string `json:"url"`
	}{URL: rawURL})
	if err != nil {
		return nil, err
	}
	response, err := r.base.fetch(
		ctx,
		http.MethodPost,
		r.base.baseURL+"/web_bot_auth/sign",
		http.Header{"Content-Type": []string{"application/json"}},
		requestBody,
	)
	if err != nil {
		return nil, err
	}
	if response.status < 200 || response.status >= 300 {
		return nil, newAPIError("get web bot auth headers", response.status, response.data, response.rawBody)
	}
	if err := decodeResponse("get web bot auth headers", response, &envelope); err != nil {
		return nil, err
	}
	block := envelope.WebBotAuth
	if block.Signature == "" || block.SignatureInput == "" || block.SignatureAgent == "" || block.Authority == "" || block.ExpiresAt == "" {
		return nil, newResponseError("get web bot auth headers", response.status, errors.New("response is missing required signing fields"))
	}
	expiresAt, err := time.Parse(time.RFC3339, block.ExpiresAt)
	if err != nil {
		return nil, newResponseError("get web bot auth headers", response.status, fmt.Errorf("invalid expires_at %q: %w", block.ExpiresAt, err))
	}
	r.mu.Lock()
	r.cache[authority] = webBotAuthCacheEntry{block: block, expiresAt: expiresAt}
	r.mu.Unlock()
	return &envelope.WebBotAuth, nil
}

import { z } from 'zod';
import type { LinkOptions } from '@/config';
import { BaseResource } from '@/resources/base';
import type {
  ITransactionsResource,
  ListTransactionsParams,
} from '@/resources/interfaces';
import type { TransactionsPage } from '@/types/index';

const transactionSchema = z.looseObject({
  id: z.string(),
  source_id: z.string().nullable(),
  amount: z.number(),
  currency: z.string(),
  created_date: z.string(),
  description: z.string(),
  origin: z.enum(['link', 'external_connection']),
  category: z.string().nullable(),
  status: z.string(),
});
const transactionsPageSchema = z.union([
  z.array(transactionSchema).transform((data) => ({ data })),
  z.looseObject({
    data: z.array(transactionSchema),
    has_more: z.boolean().optional(),
  }),
]);

export class TransactionsResource
  extends BaseResource
  implements ITransactionsResource
{
  constructor(options: LinkOptions) {
    super(options, '/transactions');
  }

  private buildUrl(params: ListTransactionsParams): string {
    const url = new URL(this.endpoint);

    if (params.limit !== undefined) {
      url.searchParams.set('limit', String(params.limit));
    }
    if (params.starting_after !== undefined) {
      url.searchParams.set('starting_after', params.starting_after);
    }
    if (params.ending_before !== undefined) {
      url.searchParams.set('ending_before', params.ending_before);
    }
    if (params.start_date !== undefined) {
      url.searchParams.set('date_start', params.start_date);
    }
    if (params.end_date !== undefined) {
      url.searchParams.set('date_end', params.end_date);
    }
    if (params.category !== undefined) {
      url.searchParams.set('category', params.category);
    }
    if (params.origin !== undefined) {
      url.searchParams.set('origin', params.origin);
    }
    if (params.sources !== undefined) {
      for (const source of params.sources) {
        url.searchParams.append('sources[]', source);
      }
    }

    return url.toString();
  }

  async list(params: ListTransactionsParams = {}): Promise<TransactionsPage> {
    const { status, data, rawBody } = await this.apiFetch({
      method: 'GET',
      url: this.buildUrl(params),
    });

    if (status < 200 || status >= 300) {
      this.throwApiError('list transactions', status, data, rawBody);
    }

    return this.parseResponse(
      'list transactions',
      status,
      () => transactionsPageSchema.parse(data) as TransactionsPage,
    );
  }
}

import { z } from 'zod';
import type { LinkOptions } from '@/config';
import { LinkSdkError } from '@/errors';
import { BaseResource } from '@/resources/base';
import type { IWebBotAuthResource } from '@/resources/interfaces';
import type { WebBotAuthBlock } from '@/types/index';

interface CacheEntry {
  block: WebBotAuthBlock;
  expiresAt: number;
}

const EXPIRY_BUFFER_MS = 30_000;

const webBotAuthBlockSchema = z.looseObject({
  signature: z.string(),
  signature_input: z.string(),
  signature_agent: z.string(),
  authority: z.string(),
  expires_at: z.string(),
});
const webBotAuthResponseSchema = z.looseObject({
  web_bot_auth: webBotAuthBlockSchema,
});

export class WebBotAuthResource
  extends BaseResource
  implements IWebBotAuthResource
{
  private readonly cache = new Map<string, CacheEntry>();

  constructor(options: LinkOptions) {
    super(options, '/web_bot_auth/sign');
  }

  async signUrl(url: string): Promise<WebBotAuthBlock> {
    let authority: string;
    try {
      authority = new URL(url).hostname;
    } catch (error) {
      throw new LinkSdkError(`Invalid URL: ${url}`, { cause: error });
    }

    const cached = this.cache.get(authority);
    if (cached && Date.now() < cached.expiresAt - EXPIRY_BUFFER_MS) {
      return cached.block;
    }

    const { status, data, rawBody } = await this.apiFetch({
      method: 'POST',
      url: this.endpoint,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ url }),
    });

    if (status < 200 || status >= 300) {
      this.throwApiError('get web bot auth headers', status, data, rawBody);
    }

    const webBotAuth = this.parseResponse(
      'get web bot auth headers',
      status,
      () => webBotAuthResponseSchema.parse(data).web_bot_auth,
    );
    const expiresAt = Date.parse(webBotAuth.expires_at);
    if (Number.isNaN(expiresAt)) {
      throw new LinkSdkError(
        `Credentials response has invalid expires_at: ${webBotAuth.expires_at}`,
      );
    }

    this.cache.set(authority, { block: webBotAuth, expiresAt });
    return webBotAuth;
  }
}

"""Per-client Web Bot Auth cache, shared across paths and ports on a hostname."""

from datetime import UTC, datetime, timedelta
from threading import Lock
from urllib.parse import urlsplit

from ._operations import signing_expiry, web_bot_sign
from ._transport import AsyncTransport, Transport
from .errors import LinkSDKError
from .models import WebBotAuthBlock


def _now() -> datetime:
    return datetime.now(UTC)


def _authority(url: str) -> str:
    try:
        parsed = urlsplit(url)
        if not parsed.scheme or not parsed.hostname:
            raise ValueError("URL must be absolute")
        _ = parsed.port
        return parsed.hostname
    except ValueError as error:
        raise LinkSDKError("Invalid URL: " + url) from error


class _Cache:
    def __init__(self) -> None:
        self._lock = Lock()
        self._entries: dict[str, tuple[datetime, WebBotAuthBlock]] = {}

    def get(self, authority: str) -> WebBotAuthBlock | None:
        with self._lock:
            cached = self._entries.get(authority)
            if cached and cached[0] - _now() > timedelta(seconds=30):
                return cached[1].model_copy(deep=True)
        return None

    def put(self, authority: str, block: WebBotAuthBlock) -> None:
        expiry = signing_expiry(block.expires_at)
        with self._lock:
            self._entries[authority] = (expiry, block.model_copy(deep=True))


class WebBotAuthResource:
    def __init__(self, transport: Transport) -> None:
        self._transport = transport
        self._cache = _Cache()

    def sign_url(self, url: str) -> WebBotAuthBlock:
        """Sign a merchant URL; cache by hostname until 30s before expiry."""
        authority = _authority(url)
        cached = self._cache.get(authority)
        if cached is not None:
            return cached
        block = self._transport.request(web_bot_sign(url))
        self._cache.put(authority, block)
        return block


class AsyncWebBotAuthResource:
    def __init__(self, transport: AsyncTransport) -> None:
        self._transport = transport
        self._cache = _Cache()

    async def sign_url(self, url: str) -> WebBotAuthBlock:
        """Sign a merchant URL; cache by hostname until 30s before expiry."""
        authority = _authority(url)
        cached = self._cache.get(authority)
        if cached is not None:
            return cached
        block = await self._transport.request(web_bot_sign(url))
        self._cache.put(authority, block)
        return block

import { z } from 'zod';
import type { LinkOptions } from '@/config';
import { LinkApiError } from '@/errors';
import { BaseResource } from '@/resources/base';
import { parseHolderPublicJwk } from '@/resources/holder-jwk';
import type {
  IIdentityCredentialsResource,
  IssueIdentityCredentialParams,
  IssueIdentityCredentialResponse,
} from '@/resources/interfaces';

const LINK_ISSUER = 'https://api.link.com';
const LINK_ISSUER_METADATA_URL = `${LINK_ISSUER}/.well-known/aap-issuer`;

const identityCredentialIssuerMetadataSchema = z.looseObject({
  issuer: z.literal(LINK_ISSUER),
  credential_endpoint: z.string(),
});

const issueIdentityCredentialResponseSchema = z.looseObject({
  credential: z.string(),
  issuer: z.literal(LINK_ISSUER),
  expires_at: z.string(),
});

/** Accepts a discovered endpoint only when it remains on api.link.com. */
function requireLinkEndpoint(value: string, field: string): string {
  let url: URL;
  try {
    url = new URL(value);
  } catch (error) {
    throw new TypeError(`${field} is not a valid URL`, { cause: error });
  }
  if (
    url.protocol !== 'https:' ||
    url.origin !== LINK_ISSUER ||
    url.username ||
    url.password
  ) {
    throw new TypeError(`${field} must be an HTTPS URL on ${LINK_ISSUER}`);
  }
  return url.href;
}

export class IdentityCredentialsResource
  extends BaseResource
  implements IIdentityCredentialsResource
{
  constructor(options: LinkOptions) {
    super(options, '');
  }

  private async discoverCredentialEndpoint(): Promise<string> {
    const { status, data, rawBody } = await this.rawFetch({
      method: 'GET',
      url: LINK_ISSUER_METADATA_URL,
      redirect: 'manual',
    });
    if (status >= 300 && status < 400) {
      throw new LinkApiError(
        `Refused redirect while fetching identity credential issuer metadata (${status})`,
        { status, rawBody },
      );
    }

    if (status < 200 || status >= 300) {
      this.throwApiError(
        'fetch identity credential issuer metadata',
        status,
        data,
        rawBody,
      );
    }

    const metadata = this.parseResponse(
      'parse identity credential issuer metadata',
      status,
      () => identityCredentialIssuerMetadataSchema.parse(data),
    );
    return this.parseResponse(
      'validate identity credential issuer metadata',
      status,
      () =>
        requireLinkEndpoint(
          metadata.credential_endpoint,
          'credential_endpoint',
        ),
    );
  }

  async issue(
    params: IssueIdentityCredentialParams,
  ): Promise<IssueIdentityCredentialResponse> {
    const publicJwk = parseHolderPublicJwk(params.cnf.jwk);
    const endpoint = await this.discoverCredentialEndpoint();
    const { status, data, rawBody } = await this.apiFetch({
      method: 'POST',
      url: endpoint,
      redirect: 'manual',
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
      body: JSON.stringify({ cnf: { jwk: publicJwk } }),
    });

    if (status >= 300 && status < 400) {
      throw new LinkApiError(
        `Refused redirect while issuing identity credential (${status})`,
        { status, rawBody },
      );
    }

    if (status < 200 || status >= 300) {
      this.throwApiError('issue identity credential', status, data, rawBody);
    }

    return this.parseResponse('issue identity credential', status, () =>
      issueIdentityCredentialResponseSchema.parse(data),
    );
  }
}

import { defineChannel, GET } from 'eve/channels';
import { getLocalDevCapability } from 'eve/local-dev';
import { getAuth, getTerminalSession, sessionHeaders } from '../lib/auth';
import { authorizationIdentifier } from '../lib/link-auth';

const noCache = {
  'cache-control': 'no-store',
  'referrer-policy': 'no-referrer',
};

export default defineChannel({
  routes: [
    GET('/link/authorize/:attempt', async (_request, { params }) => {
      if (!getLocalDevCapability())
        return new Response('Local development only.', { status: 403 });
      const session = await getTerminalSession();
      const { auth } = await getAuth();
      const { internalAdapter } = await auth.$context;
      const pending = await internalAdapter.consumeVerificationValue(
        authorizationIdentifier(session.response.user.id, params.attempt ?? ''),
      );
      if (!pending) {
        return new Response('Authorization expired or invalid.', {
          status: 400,
          headers: noCache,
        });
      }
      const callbackUrl = pending.value;
      const errorCallback = new URL(callbackUrl);
      errorCallback.searchParams.set('error', 'authorization_failed');
      const result = await auth.api.connectLink({
        body: {
          callbackURL: callbackUrl,
          errorCallbackURL: errorCallback.href,
        },
        headers: sessionHeaders(session.headers),
        returnHeaders: true,
      });
      const headers = new Headers({
        ...noCache,
        location: result.response.url,
      });
      for (const cookie of [
        ...session.headers.getSetCookie(),
        ...result.headers.getSetCookie(),
      ]) {
        headers.append('set-cookie', cookie);
      }
      return new Response(null, { status: 302, headers });
    }),
    GET('/api/auth/callback/link', async (request) =>
      (await getAuth()).auth.handler(request),
    ),
  ],
});
